import os,zipfile,glob,json
for fn in sorted(glob.glob('/mnt/data/*')):
 if os.path.isfile(fn):
  if fn.lower().endswith(('.graphml','.json','.zip','.csv','.md')):
   size=os.path.getsize(fn)
   if fn.endswith('.zip'):
    try:
     with zipfile.ZipFile(fn) as z:
      names=z.namelist(); sizes=sum(x.file_size for x in z.infolist())
      print('ZIP',os.path.basename(fn), 'compressed',size,'members',len(names),'uncompressed',sizes,'examples',names[:15])
